// ── Motion: one vocabulary for everything that moves ──────────
//
// Springs are set the way Apple sets them — a duration and a bounce —
// and written as CSS linear() curves, so the same curve drives a CSS
// animation (tokens.css: --spring-*) and a Web Animations call here.
// Where linear() is missing (Safari < 17.2, Chrome < 113) a spring falls
// back to a cubic-bezier with the same character: an overshoot for the
// bouncy ones, the house ease-out for the rest.
//
// The numbers in tokens.css are generated by springCurve() below, and
// tests/motion.test.mjs fails if the two ever drift apart.
//
// Reduced motion follows the phone (there is no setting in the app):
// reducedMotion() is read at the moment something would move, so
// flipping the system switch takes effect on the next animation.

export const EASE = {
  out:  'cubic-bezier(0.2, 0, 0, 1)',
  exit: 'cubic-bezier(0.4, 0, 1, 1)',
  wipe: 'cubic-bezier(0.7, 0, 0.2, 1)',
  io:   'cubic-bezier(0.45, 0, 0.55, 1)',
  overshoot: 'cubic-bezier(0.34, 1.4, 0.64, 1)',
}

/**
 * A damped spring sampled into 49 points. `dur` is the perceptual
 * duration in seconds (one period of the undamped spring), `bounce` 0–0.9.
 * Returns the points and the time it takes to settle within 0.2%.
 */
export function springCurve(dur, bounce) {
  const z = 1 - Math.max(0, Math.min(0.9, bounce))
  const w0 = (2 * Math.PI) / dur
  const settle = Math.min(2.5, -Math.log(0.002) / (z * w0))
  const N = 48
  const pts = []
  for (let i = 0; i <= N; i++) {
    const t = (settle * i) / N
    let x
    if (z < 1) {
      const wd = w0 * Math.sqrt(1 - z * z)
      x = 1 - Math.exp(-z * w0 * t) * (Math.cos(wd * t) + ((z * w0) / wd) * Math.sin(wd * t))
    } else {
      x = 1 - Math.exp(-w0 * t) * (1 + w0 * t)
    }
    pts.push(+x.toFixed(4))
  }
  pts[N] = 1
  return { points: pts, ms: Math.round(settle * 1000) }
}

/** The named springs. Keep in step with --spring-* in tokens.css. */
export const SPRINGS = {
  snappy: [0.35, 0.15],   // numbers rolling, a row settling
  bouncy: [0.5, 0.35],    // the trophy landing
  smooth: [0.45, 0],      // the next exercise sliding in
  sheet:  [0.42, 0.12],
}

let linearOk = null
const supportsLinear = () => {
  if (linearOk == null) {
    try { linearOk = !!(window.CSS?.supports?.('animation-timing-function', 'linear(0, 1)')) } catch { linearOk = false }
  }
  return linearOk
}

const cache = {}
/** { easing, ms } for a named spring, linear() where the browser has it. */
export function spring(name) {
  if (cache[name]) return cache[name]
  const [dur, bounce] = SPRINGS[name] || SPRINGS.smooth
  const c = springCurve(dur, bounce)
  cache[name] = supportsLinear()
    ? { easing: `linear(${c.points.join(', ')})`, ms: c.ms }
    : { easing: bounce > 0.05 ? EASE.overshoot : EASE.out, ms: Math.round(dur * 1000) }
  return cache[name]
}

export function reducedMotion() {
  try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches } catch { return false }
}

/**
 * element.animate(), never throwing: returns the Animation or null.
 * `o.spring` names a spring (its curve and settle time win over `o.d`/`o.e`).
 *
 * The fill is 'backwards' unless asked otherwise: an entrance holds its
 * first frame through its delay, and once it has played the element is
 * its own again. A finished animation that kept its last frame ('both',
 * 'forwards') would sit on top of everything set later — the swipe's
 * inline transform, a :active press, a CSS exit — so only something that
 * must stay where it ended (a card fading out before it unmounts) asks
 * for 'forwards' or 'both'.
 */
export function animate(el, keyframes, o = {}) {
  if (!el || typeof el.animate !== 'function') return null
  const sp = o.spring ? spring(o.spring) : null
  try {
    return el.animate(keyframes, {
      duration: sp ? sp.ms : (o.d ?? 240),
      delay: o.delay || 0,
      easing: sp ? sp.easing : (o.e || EASE.out),
      fill: o.fill || 'backwards',
      iterations: o.iterations || 1,
    })
  } catch { return null }
}

const pad = (s, len, left) => {
  while (s.length < len) s = left ? ' ' + s : s + ' '
  return s
}

/**
 * The columns of a rolling number (RollNumber.jsx): pairs of [old char,
 * new char], blank as ' ', integer parts right-aligned and decimal parts
 * left-aligned so the two numbers line up on the point.
 */
export function rollColumns(from, to) {
  const [ai, af = ''] = String(from).split('.')
  const [bi, bf = ''] = String(to).split('.')
  const L = Math.max(ai.length, bi.length)
  const M = Math.max(af ? af.length + 1 : 0, bf ? bf.length + 1 : 0)
  const pa = pad(ai, L, true) + pad(af ? '.' + af : '', M, false)
  const pb = pad(bi, L, true) + pad(bf ? '.' + bf : '', M, false)
  return [...pb].map((c, i) => [pa[i], c])
}

/** Rise in from `px` below, fading — the entrance most lines use. */
export const rise = (px = 8) => [{ opacity: 0, transform: `translateY(${px}px)` }, { opacity: 1, transform: 'none' }]
export const fadeIn = [{ opacity: 0 }, { opacity: 1 }]

// ── The rest's last three seconds (InlineRest) ──
export const FINAL_SECONDS = 3
/** The countdown is in its last three seconds (and not paused). */
export const isRestFinal = (left, paused = false) => !paused && left > 0 && left <= FINAL_SECONDS
/**
 * The delay (s) of the bar's blue-to-green tint, for a rest with `msLeft`
 * to go: it starts when three seconds are left — later if more remain,
 * already part-way (a negative delay) if fewer do.
 */
export const restTintDelay = (msLeft) => Math.round((Math.max(0, msLeft) / 1000 - FINAL_SECONDS) * 1000) / 1000
